const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Phoenix area
  const phoenix = ee.Geometry.Point([-112.07, 33.45]);
  const region = phoenix.buffer(10000); // 10km radius

  // Summer 2023 period (June-September to capture potential streak)
  const startDate = '2023-06-01';
  const endDate = '2023-09-30';

  // Get MODIS Terra LST daily data
  let col = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterBounds(phoenix)
    .filterDate(startDate, endDate)
    .select(['LST_Day_1km', 'QC_Day']);

  const colSize = col.size().getInfo();
  console.log(`Images found: ${colSize}`);

  if (colSize === 0) {
    console.log('No images found for summer 2023');
    console.log('<answer>C1</answer>');
    return;
  }

  // Convert collection to list and process each day
  const colList = col.toList(colSize);
  const dates = [];
  const temps = [];

  for (let i = 0; i < colSize; i++) {
    const img = ee.Image(colList.get(i));
    const date = img.date().format('YYYY-MM-dd').getInfo();

    // Get LST value (in Kelvin * 0.02 scale factor)
    const lstValue = img.select('LST_Day_1km').reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    if (lstValue !== null) {
      // Convert from Kelvin to Fahrenheit: K * 0.02 to get K, then (K - 273.15) * 9/5 + 32
      const tempK = lstValue * 0.02;
      const tempF = (tempK - 273.15) * 9/5 + 32;
      dates.push(date);
      temps.push(tempF);
    }
  }

  console.log(`Valid temperature readings: ${temps.length}`);

  if (temps.length === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  // Find longest consecutive streak above 110°F
  let maxStreak = 0;
  let currentStreak = 0;
  let streakStart = null;

  for (let i = 0; i < temps.length; i++) {
    if (temps[i] > 110) {
      if (currentStreak === 0) {
        streakStart = dates[i];
      }
      currentStreak++;
      if (currentStreak > maxStreak) {
        maxStreak = currentStreak;
      }
    } else {
      currentStreak = 0;
    }
  }

  console.log(`Longest consecutive streak: ${maxStreak} days`);
  console.log(`Days above 110°F: ${temps.filter(t => t > 110).length}/${temps.length}`);
  console.log(`Max temp: ${Math.max(...temps).toFixed(1)}°F`);
  console.log(`Min temp: ${Math.min(...temps).toFixed(1)}°F`);

  // Check for unrealistic values
  if (Math.max(...temps) > 160 || Math.min(...temps) < 0) {
    console.log('Unrealistic temperature values detected');
    console.log('<answer>C3</answer>');
    return;
  }

  if (maxStreak >= 40) {
    console.log(`Found ${maxStreak} consecutive days exceeding 110°F`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`Only ${maxStreak} consecutive days found, less than 40`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
